// 中文帧的回复池：同一帧随机取一条，这是设备端最便宜的多样性来源——
// 反复问同一句，措辞在 4~6 条里轮换，而不是同一句原样复读。
//
// 抽的时候躲两件事：上一条回复本身（同一个问题连问两次不复读），
// 以及首字已被禁的候选（和模型的禁首字共用同一个环，免得规则答完
// 模型又用同一个字开头）。全躲不开就退回随机那条。
static const char* pick_flash(const char* const* arr, size_t n) {
    if (n == 0) return NULL;
    size_t start = (size_t)(rand01() * (float)n);
    if (start >= n) start = n - 1;
    const char* fallback = (const char*)pgm_read_ptr(&arr[start]);
    for (size_t k = 0; k < n; ++k) {
        const char* p = (const char*)pgm_read_ptr(&arr[(start + k) % n]);
        if (p == s_last_flash) continue;
        if (flash_starts_banned(p)) continue;
        s_last_flash = p;
        return p;
    }
    s_last_flash = fallback;
    return fallback;
}

